```java
import java.io.*;
import java.util.*;

public class Main {
    // 读取整数的简洁输入（基于 BufferedInputStream，适配大数据）
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;
        FastScanner(InputStream is) { in = is; }
        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
        int nextInt() throws IOException {
            int c, sgn = 1, x = 0;
            do { c = read(); } while (c <= 32);
            if (c == '-') { sgn = -1; c = read(); }
            while (c > 32) {
                x = x * 10 + (c - '0');
                c = read();
            }
            return x * sgn;
        }
    }

    static void solve(FastScanner fs) throws Exception {
        int n = fs.nextInt();
        int q = fs.nextInt();
        int[] a = new int[n + 1];
        int MAXA = 200000;

        for (int i = 1; i <= n; i++) a[i] = fs.nextInt();

        // 预处理每个数的所有因子
        ArrayList<Integer>[] divisors = new ArrayList[MAXA + 1];
        for (int i = 0; i <= MAXA; i++) divisors[i] = new ArrayList<>();
        for (int d = 1; d <= MAXA; d++) {
            for (int m = d; m <= MAXA; m += d) {
                divisors[m].add(d);
            }
        }

        // 维护能被 d 整除的数量
        int[] cntMul = new int[MAXA + 1];
        for (int i = 1; i <= n; i++) {
            int v = a[i];
            for (int d : divisors[v]) cntMul[d]++;
        }

        StringBuilder sb = new StringBuilder();
        for (int qi = 0; qi < q; qi++) {
            int t = fs.nextInt();
            if (t == 1) {
                int k = fs.nextInt();
                sb.append(cntMul[k]).append('\n');
            } else {
                int idx = fs.nextInt();
                int x = fs.nextInt();
                int old = a[idx];
                if (old != x) {
                    for (int d : divisors[old]) cntMul[d]--;
                    for (int d : divisors[x]) cntMul[d]++;
                    a[idx] = x;
                } else {
                    a[idx] = x;
                }
            }
        }
        System.out.print(sb.toString());
    }

    // 主函数：只做输入输出调度
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        solve(fs);
    }
}
```

